const std=@import("std");const E=@import("experimental/shared_pace.zig");const P=@import("simulation/microbes.zig");
test "diagnose frozen failing equal pace stable rare control without changing budgets"{
 for([_]f64{0,0.2})|rate|{var s=E.State{.cell=E.M.initialized(42)};s.cell.nutrient=0.1;s.cell.cohorts[0]=.{.lineage=1,.biomass=0.2*0.05};s.cell.cohorts[1]=.{.lineage=2,.biomass=0.2-s.cell.cohorts[0].biomass};const n0=E.preciseN(s);var maintenance:f64=0;var core:f64=0;var abs_m:f64=0;var abs_c:f64=0;for(0..3360)|tick|{const r=E.step(&s,.{1,1,1,1},rate,1,1440).?;maintenance+=r.maintenance_n_error;core+=r.core_n_error;abs_m+=@abs(r.maintenance_n_error);abs_c+=@abs(r.core_n_error);try std.testing.expectApproxEqAbs(E.preciseN(s)-n0,maintenance+core,1e-12);if(tick+1==3000 or tick+1==3360)std.debug.print("DRIFT rate={d} tick={d} precise_delta={e} maintenance_signed={e} core_signed={e} maintenance_absolute_bound={e} core_absolute_bound={e} counter_identity_residual={e}\n",.{rate,tick+1,E.preciseN(s)-n0,maintenance,core,abs_m,abs_c,E.preciseN(s)-n0-maintenance-core});}}
 var c=P.initialized(42);c.nutrient=0.1;c.cohorts[0]=.{.lineage=1,.biomass=0.2*0.05};c.cohorts[1]=.{.lineage=2,.biomass=0.2-c.cohorts[0].biomass};const start=P.nutrientTotal(c);var air:f64=10;var o:f64=10;for(0..3360)|_|{const f=P.step(&c,.{.temperature=303,.depth_km=0.001,.light=1,.carbon_available=@floatCast(air),.oxygen_carbon_capacity=@floatCast(o)},1440);air+=@as(f64,f.recycled)-f.fixed;o+=@as(f64,f.fixed)-f.recycled;}std.debug.print("PRODUCTION_DIRECT day=56 nutrient_delta={e} living={d}\n",.{@as(f64,P.nutrientTotal(c))-start,P.biomass(c)});
}
